phase1.code:
# Polymorphism — same interface, different behavior

print("=== Polymorphism with methods ===\n")

class Character:
    def __init__(self, name, level):
        self.name = name
        self.level = level

    def attack(self):
        return f"{self.name} attacks!"

    def defend(self):
        return f"{self.name} defends!"

class Warrior(Character):
    def attack(self):
        return f"{self.name} swings a sword!"

    def defend(self):
        return f"{self.name} raises a shield!"

class Mage(Character):
    def attack(self):
        return f"{self.name} casts a fireball!"

    def defend(self):
        return f"{self.name} conjures a magical barrier!"

class Rogue(Character):
    def attack(self):
        return f"{self.name} stabs from the shadows!"

    def defend(self):
        return f"{self.name} dodges gracefully!"

# Polymorphic usage (same interface, different results)
characters = [
    Warrior("Aragorn", 15),
    Mage("Gandalf", 50),
    Rogue("Legolas", 18)
]

for char in characters:
    print(char.attack())
    print(char.defend())
    print()

print("=== Polymorphism with functions ===\n")

# Functions that work with any object

def battle_round(attacker, defender):
    print(attacker.attack())
    print(defender.defend())
    print("---")

# Works with any Character subclass
battle_round(Warrior("Aragorn", 15), Mage("Gandalf", 50))
battle_round(Mage("Gandalf", 50), Rogue("Legolas", 18))

print("=== Polymorphism with different types ===\n")

# Duck typing — if it quacks like a duck...

class Dragon:
    def attack(self):
        return "Dragon breathes fire!"

    def defend(self):
        return "Dragon's scales deflect attacks!"

def show_attack(thing):
    # Works with anything that has attack()
    print(thing.attack())
    print(thing.defend())

# Different types
show_attack(Warrior("Aragorn", 15))
show_attack(Dragon())

print("\n=== isinstance with polymorphism ===\n")

for char in characters:
    if isinstance(char, Warrior):
        print(f"{char.name} is a Warrior")
    elif isinstance(char, Mage):
        print(f"{char.name} is a Mage")
    elif isinstance(char, Rogue):
        print(f"{char.name} is a Rogue")

phase2.brokenCode:
# Calling a method that doesn't exist (duck typing failure)

class Bird:
    def fly(self):
        return "Flying!"

class Fish:
    def swim(self):
        return "Swimming!"

def make_move(creature):
    return creature.fly()  # Fish doesn't have fly()!

# This works
bird = Bird()
print(make_move(bird))

# This fails
fish = Fish()
print(make_move(fish))  # ERROR!

phase2.explanation:
**AttributeError: method doesn't exist on the object!**

**What's wrong:**
1. `Fish` doesn't have a `fly()` method
2. Duck typing requires the method to exist
3. Python doesn't check at compile time
4. Runtime error

**The fix:**
```python
class Bird:
    def fly(self):
        return "Flying!"

class Fish:
    def swim(self):
        return "Swimming!"

# Method 1: Check if method exists
def make_move(creature):
    if hasattr(creature, "fly"):
        return creature.fly()
    elif hasattr(creature, "swim"):
        return creature.swim()
    else:
        return "Can't move"

# Method 2: Use try/except
def make_move(creature):
    try:
        return creature.fly()
    except AttributeError:
        return creature.swim()
```

**Python-chan says:**
"Duck typing is powerful but requires that objects actually have the methods you're calling. Check existence if unsure."

phase3.solution:
class Attack:
    def execute(self):
        return "Generic attack"

class SwordAttack(Attack):
    def execute(self):
        return "Sword slash!"

class FireAttack(Attack):
    def execute(self):
        return "Fire blast!"

class IceAttack(Attack):
    def execute(self):
        return "Ice shard!"

class HealAttack(Attack):
    def execute(self):
        return "Healing light!"

class Combatant:
    def __init__(self, name):
        self.name = name
        self.attacks = []

    def add_attack(self, attack):
        self.attacks.append(attack)

    def perform_all_attacks(self):
        print(f"{self.name}'s attacks:")
        for attack in self.attacks:
            print(f"  {attack.execute()}")

# Create combatant
aragorn = Combatant("Aragorn")

# Add attacks (polymorphic!)
aragorn.add_attack(SwordAttack())
aragorn.add_attack(FireAttack())
aragorn.add_attack(IceAttack())
aragorn.add_attack(HealAttack())

# Execute all (different behavior, same interface!)
aragorn.perform_all_attacks()
